  "version" integer NOT NULL DEFAULT '1',
  "returned_until" timestamp(3) DEFAULT NULL,
  "file_id" varchar(36) DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "submissions__assessment_id" UNIQUE ("assessment_id","user_id")
);
CREATE INDEX "submissions__user_id" ON "submissions" ("user_id");
CREATE INDEX "submissions__graded_by" ON "submissions" ("graded_by");

