CREATE TABLE "timetable_sessions" (
  "id" varchar(36) NOT NULL,
  "org_id" varchar(36) NOT NULL,
  "course_id" varchar(36) NOT NULL,
  "batch_id" varchar(36) NOT NULL,
  "teacher_id" varchar(36) NOT NULL,
  "title" varchar(160) NOT NULL,
  "room" varchar(120) NOT NULL DEFAULT '',
  "meeting_url" varchar(2000) NOT NULL DEFAULT '',
  "starts_at" timestamp(3) NOT NULL,
  "ends_at" timestamp(3) NOT NULL,
  "status" varchar(9) NOT NULL DEFAULT 'draft' CHECK ("status" IN ('draft','published','cancelled')),
  "version" integer NOT NULL DEFAULT '1',
  "created_by" varchar(36) NOT NULL,
  "updated_at" timestamp(3) NOT NULL DEFAULT (CURRENT_TIMESTAMP(3) AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);
CREATE INDEX "timetable_sessions__org_id" ON "timetable_sessions" ("org_id","starts_at");
CREATE INDEX "timetable_sessions__batch_id" ON "timetable_sessions" ("batch_id","starts_at");
CREATE INDEX "timetable_sessions__teacher_id" ON "timetable_sessions" ("teacher_id","starts_at");
CREATE INDEX "timetable_sessions__course_id" ON "timetable_sessions" ("course_id");
CREATE INDEX "timetable_sessions__created_by" ON "timetable_sessions" ("created_by");

CREATE TABLE "tutoring_course_decks" (
  "deck_id" varchar(36) NOT NULL,
  "course_id" varchar(36) NOT NULL,
  "title" varchar(140) NOT NULL,
  "theme" varchar(5) NOT NULL CHECK ("theme" IN ('ocean','amber','iris')),
  "cards_json" jsonb NOT NULL,
  "revision" bigint NOT NULL,
  "shared_at" timestamp(3) NOT NULL DEFAULT (CURRENT_TIMESTAMP(3) AT TIME ZONE 'UTC'),
  PRIMARY KEY ("deck_id","course_id")
);
CREATE INDEX "tutoring_course_decks__ix_tutoring_course" ON "tutoring_course_decks" ("course_id","shared_at");

CREATE TABLE "tutoring_decks" (
  "id" varchar(36) NOT NULL,
  "org_id" varchar(36) NOT NULL,
  "author_id" varchar(36) NOT NULL,
