  "title" varchar(140) NOT NULL,
  "theme" varchar(5) NOT NULL CHECK ("theme" IN ('ocean','amber','iris')),
  "cards_json" jsonb NOT NULL,
  "revision" bigint NOT NULL DEFAULT '1',
  "updated_at" timestamp(3) NOT NULL DEFAULT (CURRENT_TIMESTAMP(3) AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);
CREATE INDEX "tutoring_decks__ix_tutoring_author" ON "tutoring_decks" ("org_id","author_id","updated_at");
CREATE INDEX "tutoring_decks__author_id" ON "tutoring_decks" ("author_id");

