CREATE TABLE "sessions" (
  "token_hash" varchar(64) NOT NULL,
  "user_id" varchar(36) NOT NULL,
  "expires_at" timestamp(3) NOT NULL,
  "created_at" timestamp(3) NOT NULL DEFAULT (CURRENT_TIMESTAMP(3) AT TIME ZONE 'UTC'),
  PRIMARY KEY ("token_hash")
);
CREATE INDEX "sessions__idx_sessions_user" ON "sessions" ("user_id");
CREATE INDEX "sessions__idx_sessions_expiry" ON "sessions" ("expires_at");

CREATE OR REPLACE FUNCTION tejasvi_touch() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW IS DISTINCT FROM OLD AND to_jsonb(NEW)->TG_ARGV[0] IS NOT DISTINCT FROM to_jsonb(OLD)->TG_ARGV[0] THEN
    NEW := jsonb_populate_record(NEW, jsonb_build_object(TG_ARGV[0], (CURRENT_TIMESTAMP(3) AT TIME ZONE 'UTC')));
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "ai_workspace_settings__updated_at_touch" BEFORE UPDATE ON "ai_workspace_settings" FOR EACH ROW EXECUTE FUNCTION tejasvi_touch('updated_at');
CREATE TRIGGER "gamma_presentations__updated_at_touch" BEFORE UPDATE ON "gamma_presentations" FOR EACH ROW EXECUTE FUNCTION tejasvi_touch('updated_at');
CREATE TRIGGER "question_bank__updated_at_touch" BEFORE UPDATE ON "question_bank" FOR EACH ROW EXECUTE FUNCTION tejasvi_touch('updated_at');
CREATE TRIGGER "quiz_extensions__updated_at_touch" BEFORE UPDATE ON "quiz_extensions" FOR EACH ROW EXECUTE FUNCTION tejasvi_touch('updated_at');
CREATE TRIGGER "tutoring_decks__updated_at_touch" BEFORE UPDATE ON "tutoring_decks" FOR EACH ROW EXECUTE FUNCTION tejasvi_touch('updated_at');

CREATE VIEW "memberships" AS select "institution_memberships"."org_id" AS "org_id","institution_memberships"."user_id" AS "user_id","institution_memberships"."role" AS "role","institution_memberships"."class_name" AS "class_name","institution_memberships"."reference_number" AS "reference_number","institution_memberships"."created_at" AS "created_at","institution_memberships"."display_name" AS "display_name" from "institution_memberships" where (("institution_memberships"."active" = 1) and ("institution_memberships"."role" <> 'ops')) WITH CASCADED CHECK OPTION;

